-- v2 (D-11) replay slice, Figma K2, sessions created 2026-11-20 12:00-14:00 UTC (9,156 sessions; 3.5 s; no sampling).
-- Same CTEs and thresholds as 04_replay_figma_20nov_v2.sql; time filter as v1 06_replay_figma_20nov_1200_1400.sql.
-- Output trimmed vs v1 (no T2/T4/today-only rates) to keep the response small; HAVING keeps cells with any fire plus dict totals.
WITH thr(d,grp,tst,tlt) AS (SELECT * FROM VALUES (-1,'Desktop',11,660),(-1,'Mobile',11,660),(-1,'Linux',11,660),(-1,'WinRDVM',11,660),(-1,'Other',11,660),(1,'Desktop',7.49,449.4),(1,'Mobile',7.49,449.4),(1,'Linux',7.49,449.4),(1,'WinRDVM',7.49,449.4),(1,'Other',7.49,449.4),(3,'Desktop',7,420),(3,'Mobile',9,540),(3,'Linux',6,360),(3,'WinRDVM',5,300),(3,'Other',8,480),(7,'Desktop',6.0,480),(7,'Mobile',3.0,240),(7,'Linux',6.0,480),(7,'WinRDVM',6.0,480),(7,'Other',6.0,480),(15,'Desktop',6,720),(15,'Mobile',6,720),(15,'Linux',6,720),(15,'WinRDVM',6.0,480),(15,'Other',6,660),(31,'Desktop',6,720),(31,'Mobile',4,480),(31,'Linux',6,720),(31,'WinRDVM',4.5,360),(31,'Other',6,660),(63,'Desktop',8,1440),(63,'Mobile',10,1800),(63,'Linux',6,1080),(63,'WinRDVM',6.0,480),(63,'Other',8,660)), s0 AS (SELECT session, session_ts ts, di_dictionary_num_matched_at_session_created d, di_matched_signature_at_session_created ms, os_at_session_created os, COALESCE(webgl_unmasked_renderer_at_session_created,'') r, COALESCE(cdn__ja4_hash_at_session_created,'') ja4, COALESCE(ua_at_session_created,'') ua, IFF(latest_risk_band='High',1,0) hi, IFF(sessions_verified>0,1,0) ver, IFF(was_challenged>0,1,0) chl, IFF(was_challenged>0 AND COALESCE(sessions_solved,0)=0,1,0) chns, di_short_term_count_at_session_created stc, di_long_term_count_at_session_created ltc, COALESCE(di_short_term_threshold_ratio_at_session_created,0) str, IFF(di_short_term_threshold_breached_at_session_created,1,0) stb, IFF(di_long_term_threshold_breached_at_session_created,1,0) ltb FROM ARK_PROD.STARFLEET.PROD_INT_SESSION_SUMMARY WHERE public_key='A207F8A1-ED09-4325-ACE6-C8E26A458FBA' AND session_last_timestamp>='2026-11-20 12:00' AND session_last_timestamp<'2026-11-21 06:00' AND session_ts>='2026-11-20 12:00' AND session_ts<'2026-11-20 14:00' AND di_dictionary_num_matched_at_session_created IS NOT NULL), s1 AS (SELECT s0.*, CASE WHEN r ILIKE '%SwiftShader%' OR r ILIKE '%llvmpipe%' OR r ILIKE '%VirtualBox%' OR r ILIKE '%VMware%' THEN 'A' WHEN r ILIKE '%Basic Render Driver%' AND COALESCE(os,'')<>'Windows' THEN 'B' WHEN COALESCE(os,'') IN ('','--') AND r<>'' THEN 'B' WHEN ja4 LIKE 't%' AND SPLIT_PART(ja4,'_',2) IN ('a09f3c656075','2802a3db6c62') AND os IN ('Windows','GNU/Linux','Ubuntu','Chrome OS') THEN 'C' WHEN ua LIKE '%Chrome/%' AND RIGHT(SPLIT_PART(ja4,'_',1),2)='h1' THEN 'C' WHEN TRY_TO_NUMBER(REGEXP_SUBSTR(ua,'Chrome/([0-9]+)',1,1,'e',1))>=70 AND ja4 LIKE 't12%' THEN 'C' END AS x, CASE WHEN r ILIKE '%Basic Render Driver%' AND os='Windows' THEN 'WinRDVM' WHEN os IN ('Windows','OS X','Chrome OS') THEN 'Desktop' WHEN os IN ('iOS','iPadOS','Android') THEN 'Mobile' WHEN os IN ('GNU/Linux','Ubuntu') THEN 'Linux' ELSE 'Other' END AS grp0 FROM s0), s2 AS (SELECT s1.*, IFF(x IS NULL, grp0, 'SKIP_'||x) grp, IFF(x IS NULL AND SUM(hi) OVER (PARTITION BY x, grp0, ms, TIME_SLICE(ts,40,'MINUTE')) / COUNT(*) OVER (PARTITION BY x, grp0, ms, TIME_SLICE(ts,40,'MINUTE')) < 0.2, 1, 0) cl FROM s1), f AS (SELECT s2.d, s2.grp, hi, ver, chl, chns, cl, stb t, IFF(str>=2,1,0) t2, IFF(str>=4,1,0) t4, ltb tl, IFF(stc>11,1,0) t11, IFF(stc>thr.tst,1,0) n, IFF(ltc>thr.tlt,1,0) nl, IFF(stc>thr.tst OR ltc>thr.tlt,1,0) na FROM s2 LEFT JOIN thr ON thr.d=s2.d AND thr.grp=s2.grp) SELECT COALESCE(d::STRING,'ALL')||'|'||COALESCE(grp,'ALL')||'|n='||COUNT(*)||'|hi='||ROUND(100*AVG(hi),1)||'|cl='||SUM(cl)||'|T='||SUM(t)||'/'||COALESCE(ROUND(100*SUM(t*hi)/NULLIF(SUM(t),0),1)::STRING,'-')||'/'||COALESCE(ROUND(100*SUM(t*ver)/NULLIF(SUM(t),0),1)::STRING,'-')||'/'||COALESCE(ROUND(100*SUM(t*chl)/NULLIF(SUM(t),0),1)::STRING,'-')||'/'||COALESCE(ROUND(100*SUM(t*chns)/NULLIF(SUM(t),0),1)::STRING,'-')||'|TL='||SUM(tl)||'|NL='||SUM(nl)||'|NA='||SUM(na)||'/'||COALESCE(ROUND(100*SUM(na*hi)/NULLIF(SUM(na),0),1)::STRING,'-')||'/'||COALESCE(ROUND(100*SUM(na*ver)/NULLIF(SUM(na),0),1)::STRING,'-')||'/'||COALESCE(ROUND(100*SUM(na*chl)/NULLIF(SUM(na),0),1)::STRING,'-')||'/'||COALESCE(ROUND(100*SUM(na*chns)/NULLIF(SUM(na),0),1)::STRING,'-') ||'|NEWONLY='||SUM(na*(1-GREATEST(t,tl)))||'/'||COALESCE(ROUND(100*SUM(na*(1-GREATEST(t,tl))*hi)/NULLIF(SUM(na*(1-GREATEST(t,tl))),0),1)::STRING,'-')||'|TODAYONLY='||SUM(GREATEST(t,tl)*(1-na))||'|CLEAN_T='||SUM(cl*t)||'|CLEAN_NA='||SUM(cl*na) r FROM f GROUP BY GROUPING SETS ((d,grp),(d),()) HAVING SUM(t)+SUM(na)>0 OR grp IS NULL ORDER BY d, grp
;
